package graph

import (
	"context"
	"errors"
	"myapp/auth"
	"myapp/graph/model"
)

type MutationResolver struct {
	*Resolver
}

func (r *MutationResolver) UpdatePatientVitals(ctx context.Context, patientID string, input model.VitalsInput) (*model.Vitals, error) {
	clinician, ok := auth.ClinicianFromContext(ctx)
	if !ok {
		return nil, errors.New("clinician authentication required")
	}

	assigned, err := r.EHRService.IsClinicianAssigned(ctx, clinician.ID, patientID)
	if err != nil || !assigned {
		return nil, errors.New("forbidden: clinician not authorized for target patient")
	}

	vitals, err := r.EHRService.RecordVitals(ctx, patientID, input.Systolic, input.Diastolic, input.HeartRate)
	if err != nil {
		return nil, err
	}

	return vitals, nil
}
